import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportExportServlet extends HttpServlet {

    private static final Pattern SAFE_TABLE = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportId = req.getParameter("report_id");
        String format = req.getParameter("format"); // csv, json, xml
        String columns = req.getParameter("columns"); // comma-separated column list
        String filterExpr = req.getParameter("filter"); // SQL WHERE clause fragment

        if (reportId == null || !SAFE_TABLE.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        if (format == null) format = "csv";

        // Validate columns - allow only alphanumeric and underscores
        String[] colArray = columns != null ? columns.split(",") : new String[]{"*"};
        StringBuilder colBuilder = new StringBuilder();
        for (int i = 0; i < colArray.length; i++) {
            String col = colArray[i].trim();
            if (!SAFE_TABLE.matcher(col).matches() && !col.equals("*")) {
                resp.sendError(400, "Invalid column name: " + 
                    StringEscapeUtils.escapeHtml4(col));
                return;
            }
            if (i > 0) colBuilder.append(", ");
            colBuilder.append(col);
        }

        // Build query with user-supplied filter
        String query = "SELECT " + colBuilder.toString() + 
                      " FROM report_" + reportId;

        if (filterExpr != null && !filterExpr.isEmpty()) {
            // Basic sanitization - remove comments and semicolons
            String sanitized = filterExpr.replaceAll("--.*", "")
                                        .replaceAll("/\\*.*?\\*/", "")
                                        .replaceAll(";", "");
            query += " WHERE " + sanitized;
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getDataSource().getConnection();
            stmt = conn.createStatement();

            // Set query timeout for safety
            stmt.setQueryTimeout(30);

            rs = stmt.executeQuery(query);

            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            resp.setContentType(getContentType(format));
            PrintWriter out = resp.getWriter();

            if ("csv".equals(format)) {
                // Header row
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) out.print(",");
                    out.print(meta.getColumnName(i));
                }
                out.println();
                // Data rows
                while (rs.next()) {
                    for (int i = 1; i <= colCount; i++) {
                        if (i > 1) out.print(",");
                        String val = rs.getString(i);
                        out.print(val != null ? escapeCsv(val) : "");
                    }
                    out.println();
                }
            } else if ("json".equals(format)) {
                out.print("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",");
                    out.print("{");
                    for (int i = 1; i <= colCount; i++) {
                        if (i > 1) out.print(",");
                        out.print("\"" + meta.getColumnName(i) + "\":");
                        String val = rs.getString(i);
                        out.print(val != null ? "\"" + 
                            StringEscapeUtils.escapeJson(val) + "\"" : "null");
                    }
                    out.print("}");
                    first = false;
                }
                out.print("]");
            }

        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed");
        } finally {
            if (rs != null) try { rs.close(); } catch (Exception e) {}
            if (stmt != null) try { stmt.close(); } catch (Exception e) {}
            if (conn != null) try { conn.close(); } catch (Exception e) {}
        }
    }

    private String escapeCsv(String val) {
        if (val.contains(",") || val.contains("\"") || val.contains("\n")) {
            return "\"" + val.replace("\"", "\"\"") + "\"";
        }
        return val;
    }

    private String getContentType(String format) {
        switch(format) {
            case "json": return "application/json";
            case "xml": return "application/xml";
            default: return "text/csv";
        }
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/reportDB");
        } catch (Exception e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
